using System.Reflection;
using Comet.Fika;
using Comet.Api;
using Fika.Core.Modding;
using Fika.Core.Modding.Events;
using Fika.Core.Networking;
using Fika.Core.Networking.LiteNetLib;
using Fika.Core.Networking.LiteNetLib.Utils;

int checks=0;void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
void Call(DoorBridge b,string name,params object[] args)=>typeof(DoorBridge).GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static)!.Invoke(b,args);
var host=new DoorBridge();host.Initialize(new BepInEx.Logging.ManualLogSource());var server=new FikaServer();FikaEventDispatcher.Emit(new FikaNetworkManagerCreatedEvent(server));
var peer=new NetPeer();FikaEventDispatcher.Emit(new PeerConnectedEvent(server,peer));
Check(!DoorMotionNetwork.Ready!(),"unknown client prevents authoring custom angles");
server.Receiver!(new(){Kind=2,Door="bad"},peer);Check(!DoorMotionNetwork.Ready!(),"client cannot author state");
server.Receiver!(new(){Kind=0},peer);Check(DoorMotionNetwork.Ready!(),"matching protocol handshake enables authority");
var bot=new Fika.Core.Main.Players.FikaBot();
Check(MovementRecoveryNetwork.Teleport!(bot,new(1,0,0))&&bot.Teleports==1&&bot.BotPacketSender.Snapshots==1,"C06 host relocation immediately emits native position snapshot");
Check(!MovementRecoveryNetwork.Teleport!(bot,new(4,0,0))&&bot.Teleports==1,"C06 maximum displacement enforced again in bridge");
Check(!MovementRecoveryNetwork.Teleport!(new EFT.Player(),new(1,0,0)),"C06 cannot relocate a human or observed client");
bot.BotPacketSender.SendState=false;Check(!MovementRecoveryNetwork.Teleport!(bot,new(2,0,0)),"C06 inactive replication denied");bot.BotPacketSender.SendState=true;
string session=server.Sent.Single(x=>x.packet.Kind==1).packet.Session;
DoorMotionNetwork.Change("door",1,-90);Check(!server.Sent.Any(x=>x.packet.Kind==2),"send deferred until native packet returns");
Call(host,"Update");var sent=server.Sent.Last().packet;Check(sent.Kind==2&&sent.Angle==-90,"exact custom angle sent");
var writer=new NetDataWriter();sent.Serialize(writer);var decoded=new DoorPacket();decoded.Deserialize(new(writer.Data));
Check(decoded.Angle==-90&&decoded.Session==session&&decoded.Revision==sent.Revision,"wire serialization round trip");
var second=new NetPeer();FikaEventDispatcher.Emit(new PeerConnectedEvent(server,second));Check(!DoorMotionNetwork.Ready!(),"late peer waits for handshake");Check(!MovementRecoveryNetwork.Teleport!(bot,new(2,0,0)),"C06 late peer prevents relocation until ready");
server.Receiver!(new(){Kind=0},second);Check(server.Sent.Last().packet.Angle==-90&&server.Sent.Last().peer==second,"late peer receives current custom state");
Call(host,"AfterInteraction",new EFT.Interactive.WorldInteractiveObject());Call(host,"Update");var fence=server.Sent.Last().packet;
Check(fence.Kind==3&&fence.Revision>sent.Revision,"new interaction fences old correction");
Call(host,"Dispose");Check(DoorMotionNetwork.Ready==null&&server.Receiver==null,"host subscriptions released");

var clientBridge=new DoorBridge();clientBridge.Initialize(new BepInEx.Logging.ManualLogSource());var client=new FikaClient();FikaEventDispatcher.Emit(new FikaNetworkManagerCreatedEvent(client));Call(clientBridge,"Update");
Check(!MovementRecoveryNetwork.Teleport!(bot,new(2,0,0)),"C06 client cannot author relocation");
Check(client.Sent.Last().packet.Kind==0,"client requests handshake automatically");
client.Receiver!(new(){Kind=1,Session=session},client.ServerConnection);
client.Receiver!(sent,new NetPeer());Call(clientBridge,"Update");Check(DoorMotionNetwork.Applied.Count==0,"untrusted peer cannot change doors");
client.Receiver!(sent,client.ServerConnection);Call(clientBridge,"Update");Check(DoorMotionNetwork.Applied.Count==1,"authoritative state applied");
client.Receiver!(sent,client.ServerConnection);Call(clientBridge,"Update");Check(DoorMotionNetwork.Applied.Count==1,"duplicate revision ignored");
client.Receiver!(fence,client.ServerConnection);client.Receiver!(sent,client.ServerConnection);Call(clientBridge,"Update");Check(DoorMotionNetwork.Applied.Count==1,"stale correction cannot overwrite newer interaction");
var wrong=sent;wrong.Revision=100;wrong.Session=new string('a',32);client.Receiver!(wrong,client.ServerConnection);Call(clientBridge,"Update");Check(DoorMotionNetwork.Applied.Count==1,"foreign raid ignored");
DoorMotionNetwork.Available=false;var late=sent;late.Revision=100;client.Receiver!(late,client.ServerConnection);Call(clientBridge,"Update");
Check(DoorMotionNetwork.Applied.Count==1,"snapshot retained while late client scene loads");
DoorMotionNetwork.Available=true;UnityEngine.Time.unscaledTime=1;Call(clientBridge,"Update");
Check(DoorMotionNetwork.Applied.Count==2,"late loaded door receives retained angle");
DoorMotionNetwork.Available=false;late.Revision=101;client.Receiver!(late,client.ServerConnection);Call(clientBridge,"Update");
fence.Revision=102;client.Receiver!(fence,client.ServerConnection);DoorMotionNetwork.Available=true;UnityEngine.Time.unscaledTime=2;Call(clientBridge,"Update");
Check(DoorMotionNetwork.Applied.Count==2,"fence cancels pending late-load snapshot");
// C13: keep an old transport callback to simulate delivery after teardown/reconnect.
var oldReceiver=client.Receiver!;int applications=DoorMotionNetwork.Applied.Count;
Call(clientBridge,"EndRaid");Call(clientBridge,"EndRaid");
Check(client.Receiver==null&&!DoorMotionNetwork.Ready!(),"C13 local raid teardown unregisters transport and readiness");
oldReceiver(sent,client.ServerConnection);Call(clientBridge,"Update");
Check(DoorMotionNetwork.Applied.Count==applications,"C13 packet after end ignored");
var nextClient=new FikaClient();FikaEventDispatcher.Emit(new FikaNetworkManagerCreatedEvent(nextClient));
var nextSession=new string('b',32);nextClient.Receiver!(new(){Kind=1,Session=nextSession},nextClient.ServerConnection);
oldReceiver(new(){Kind=1,Session=session},client.ServerConnection);
oldReceiver(sent,client.ServerConnection);Call(clientBridge,"Update");
Check(DoorMotionNetwork.Applied.Count==applications,"C13 old callback cannot target new network manager");
nextClient.Receiver!(new(){Kind=1,Session=session},nextClient.ServerConnection);
nextClient.Receiver!(sent,nextClient.ServerConnection);Call(clientBridge,"Update");
Check(DoorMotionNetwork.Applied.Count==applications,"C13 stale welcome cannot roll session backwards");
var nextPacket=sent;nextPacket.Session=nextSession;nextClient.Receiver!(nextPacket,nextClient.ServerConnection);Call(clientBridge,"Update");
Check(DoorMotionNetwork.Applied.Count==applications+1,"C13 current session still applies");
Call(clientBridge,"Dispose");Check(MovementRecoveryNetwork.Teleport==null,"C06 optional bridge released");Console.WriteLine($"C04 production Fika transport: {checks} checks passed.");
